//! The bridge of Fees.FeeRule, Fees.FlatFee, Fees.PercentFee: the exports its C# façade calls (CodeCoreMorph, D-84).
use std::any::Any;
use std::ffi::{c_char, c_void};
use std::sync::Arc;

use super::ccm::{self, ccm_decimal, ccm_release_fn, ccm_status, Director, Handle, ManagedRef};
use crate::fee_rule::{self as port, FeeRule, FeeRuleBase, FlatFee, PercentFee};
use codecoremorph_runtime::{Decimal, Exception, Result};

/// `FeeRule`'s hierarchy (FeeRule, FlatFee, PercentFee) shares its root's handle type.
pub struct fees_FeeRule(());

impl Handle for fees_FeeRule {
    type Target = dyn FeeRule;
}

#[unsafe(no_mangle)]
pub extern "C" fn fees_FeeRule_release(handle: *mut fees_FeeRule) {
    ccm::release(handle);
}

#[unsafe(no_mangle)]
pub extern "C" fn fees_FeeRule_key(handle: *const fees_FeeRule) -> u64 {
    ccm::key(handle)
}

/// FeeRule's virtual members implemented in C#: a C# class derived from FeeRule, FlatFee or
/// PercentFee (a director); context is the C# object's.
pub type fees_FeeRule_fee_fn = Option<
    unsafe extern "C" fn(context: *mut c_void, amount: ccm_decimal, result: *mut ccm_decimal) -> ccm_status,
>;
pub type fees_FeeRule_applies_fn = Option<
    unsafe extern "C" fn(context: *mut c_void, amount: ccm_decimal, result: *mut bool) -> ccm_status,
>;
pub type fees_FeeRule_label_fn =
    Option<unsafe extern "C" fn(context: *mut c_void, result: *mut *mut c_char) -> ccm_status>;

type FeeFn = unsafe extern "C" fn(*mut c_void, ccm_decimal, *mut ccm_decimal) -> ccm_status;
type AppliesFn = unsafe extern "C" fn(*mut c_void, ccm_decimal, *mut bool) -> ccm_status;
type LabelFn = unsafe extern "C" fn(*mut c_void, *mut *mut c_char) -> ccm_status;

/// The C# object's virtual members, which a director calls.
#[derive(Clone, Copy)]
struct FeeRuleCalls {
    fee: FeeFn,
    applies: AppliesFn,
    label: LabelFn,
}

impl FeeRuleCalls {
    fn new(
        fee: fees_FeeRule_fee_fn,
        applies: fees_FeeRule_applies_fn,
        label: fees_FeeRule_label_fn,
    ) -> Result<FeeRuleCalls> {
        Ok(FeeRuleCalls {
            fee: ccm::callback(fee)?,
            applies: ccm::callback(applies)?,
            label: ccm::callback(label)?,
        })
    }
}

/// The ported class a C# class derives from, as its director holds it: `FeeRule`'s fields, a
/// `FlatFee` or a `PercentFee`, with that class's own implementations for the base calls, run
/// for the director (`this`).
trait FeeRuleState: Send + Sync + 'static {
    fn rule_base(&self) -> &FeeRuleBase;
    fn base_fee(&self, this: &dyn FeeRule, amount: Decimal) -> Result<Decimal>;
    fn base_applies(&self, this: &dyn FeeRule, amount: Decimal) -> Result<bool>;
    fn base_label(&self, this: &dyn FeeRule) -> Result<String>;
}

impl FeeRuleState for FeeRuleBase {
    fn rule_base(&self) -> &FeeRuleBase {
        self
    }

    fn base_fee(&self, _this: &dyn FeeRule, _amount: Decimal) -> Result<Decimal> {
        // FeeRule.Fee is abstract: no façade's body calls it.
        Err(Exception::invalid_operation("FeeRule.Fee is abstract"))
    }

    fn base_applies(&self, this: &dyn FeeRule, amount: Decimal) -> Result<bool> {
        self.applies_impl(this, amount)
    }

    fn base_label(&self, this: &dyn FeeRule) -> Result<String> {
        self.label_impl(this)
    }
}

impl FeeRuleState for FlatFee {
    fn rule_base(&self) -> &FeeRuleBase {
        self.base()
    }

    fn base_fee(&self, this: &dyn FeeRule, amount: Decimal) -> Result<Decimal> {
        self.fee_impl(this, amount)
    }

    fn base_applies(&self, this: &dyn FeeRule, amount: Decimal) -> Result<bool> {
        self.base().applies_impl(this, amount)
    }

    fn base_label(&self, this: &dyn FeeRule) -> Result<String> {
        self.base().label_impl(this)
    }
}

impl FeeRuleState for PercentFee {
    fn rule_base(&self) -> &FeeRuleBase {
        self.base()
    }

    fn base_fee(&self, this: &dyn FeeRule, amount: Decimal) -> Result<Decimal> {
        self.fee_impl(this, amount)
    }

    fn base_applies(&self, this: &dyn FeeRule, amount: Decimal) -> Result<bool> {
        self.applies_impl(this, amount)
    }

    fn base_label(&self, this: &dyn FeeRule) -> Result<String> {
        self.label_impl(this)
    }
}

/// The native object of a C# class derived from the class `S` holds: each virtual member calls
/// the C# object's, so the Rust that calls it (`charge`, `describe`, a schedule's total) runs
/// the C# override; the base calls run `S`'s own.
struct FeeRuleDirector<S: FeeRuleState> {
    director: Director,
    calls: FeeRuleCalls,
    state: S,
}

impl<S: FeeRuleState> FeeRule for FeeRuleDirector<S> {
    fn base(&self) -> &FeeRuleBase {
        self.state.rule_base()
    }

    fn fee(&self, amount: Decimal) -> Result<Decimal> {
        let mut result = ccm_decimal::default();
        // SAFETY: the function C# gave for this context, which lives as long as the director.
        ccm::check_managed(unsafe { (self.calls.fee)(self.director.context(), ccm::dec_out(amount), &mut result) })?;
        ccm::dec(result)
    }

    fn applies(&self, amount: Decimal) -> Result<bool> {
        let mut result = false;
        // SAFETY: as above.
        ccm::check_managed(unsafe { (self.calls.applies)(self.director.context(), ccm::dec_out(amount), &mut result) })?;
        Ok(result)
    }

    fn label(&self) -> Result<String> {
        let mut result: *mut c_char = std::ptr::null_mut();
        // SAFETY: as above.
        ccm::check_managed(unsafe { (self.calls.label)(self.director.context(), &mut result) })?;
        // A null label concatenates as the empty string, as in C#.
        Ok(ccm::take_str(result).unwrap_or_default())
    }
}

/// What the base calls need of a director, whichever class it derives from.
trait FeeRuleDirected {
    fn base_fee(&self, amount: Decimal) -> Result<Decimal>;
    fn base_applies(&self, amount: Decimal) -> Result<bool>;
    fn base_label(&self) -> Result<String>;
}

impl<S: FeeRuleState> FeeRuleDirected for FeeRuleDirector<S> {
    fn base_fee(&self, amount: Decimal) -> Result<Decimal> {
        self.state.base_fee(self, amount)
    }

    fn base_applies(&self, amount: Decimal) -> Result<bool> {
        self.state.base_applies(self, amount)
    }

    fn base_label(&self) -> Result<String> {
        self.state.base_label(self)
    }
}

/// The director behind a handle: a base call is a C# class's.
fn directed(handle: *const fees_FeeRule) -> Result<&'static dyn FeeRuleDirected> {
    let rule: &dyn Any = &**ccm::from_handle(handle)?;
    if let Some(d) = rule.downcast_ref::<FeeRuleDirector<FeeRuleBase>>() {
        return Ok(d);
    }
    if let Some(d) = rule.downcast_ref::<FeeRuleDirector<FlatFee>>() {
        return Ok(d);
    }
    if let Some(d) = rule.downcast_ref::<FeeRuleDirector<PercentFee>>() {
        return Ok(d);
    }
    Err(Exception::invalid_operation("a base call on an object no C# class derives from"))
}

fn new_director<S: FeeRuleState>(
    managed: Arc<ManagedRef>,
    calls: FeeRuleCalls,
    state: S,
    result_director: *mut *mut c_void,
    result: *mut *mut fees_FeeRule,
) {
    let director = Arc::new_cyclic(|this| FeeRuleDirector {
        director: Director::new(managed, this.clone()),
        calls,
        state,
    });
    ccm::put(result_director, director.director.id());
    let rule: Arc<dyn FeeRule> = director;
    ccm::put(result, ccm::to_handle::<fees_FeeRule>(rule));
}

#[unsafe(no_mangle)]
pub extern "C" fn fees_FeeRule_name(self_: *const fees_FeeRule, result: *mut *mut c_char) -> ccm_status {
    ccm::guard(|| {
        ccm::out_str(result, ccm::from_handle(self_)?.name());
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn fees_FeeRule_fee(
    self_: *const fees_FeeRule,
    amount: ccm_decimal,
    result: *mut ccm_decimal,
) -> ccm_status {
    ccm::guard(|| {
        ccm::put(result, ccm::dec_out(ccm::from_handle(self_)?.fee(ccm::dec(amount)?)?));
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn fees_FeeRule_applies(
    self_: *const fees_FeeRule,
    amount: ccm_decimal,
    result: *mut bool,
