    ccm::guard(|| {
        ccm::put(result, ccm::from_handle(self_)?.applies(ccm::dec(amount)?)?);
        Ok(())
    })
}

/// `label` is protected: only a C# class derived from FeeRule calls it, through its director.
#[unsafe(no_mangle)]
pub extern "C" fn fees_FeeRule_label(self_: *const fees_FeeRule, result: *mut *mut c_char) -> ccm_status {
    ccm::guard(|| {
        ccm::out_str(result, &directed(self_)?.base_label()?);
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn fees_FeeRule_charge(
    self_: *const fees_FeeRule,
    amount: ccm_decimal,
    result: *mut ccm_decimal,
) -> ccm_status {
    ccm::guard(|| {
        ccm::put(result, ccm::dec_out(ccm::from_handle(self_)?.charge(ccm::dec(amount)?)?));
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn fees_FeeRule_describe(
    self_: *const fees_FeeRule,
    amount: ccm_decimal,
    result: *mut *mut c_char,
) -> ccm_status {
    ccm::guard(|| {
        ccm::out_str(result, &ccm::from_handle(self_)?.describe(ccm::dec(amount)?)?);
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn fees_FeeRule_round(value: ccm_decimal, result: *mut ccm_decimal) -> ccm_status {
    ccm::guard(|| {
        ccm::put(result, ccm::dec_out(port::round(ccm::dec(value)?)?));
        Ok(())
    })
}

/// The object's class, for a façade wrapping one that comes back: 0 FlatFee, 1 PercentFee, 2 a
/// director (a C# object's, whose façade is the C# object).
#[unsafe(no_mangle)]
pub extern "C" fn fees_FeeRule_kind(self_: *const fees_FeeRule, result: *mut i32) -> ccm_status {
    ccm::guard(|| {
        let rule: &dyn Any = &**ccm::from_handle(self_)?;
        let kind = if rule.is::<FlatFee>() {
            0
        } else if rule.is::<PercentFee>() {
            1
        } else {
            2
        };
        ccm::put(result, kind);
        Ok(())
    })
}

/// A director: the native object of a C# class derived from FeeRule, FlatFee or PercentFee,
/// made by that class's constructor with the constructor's arguments. Its virtual members call
/// the C# object's (fee, applies, label); release frees the context when the director goes;
/// result_director is what ccm_director_shared takes.
#[unsafe(no_mangle)]
#[allow(clippy::too_many_arguments)]
pub extern "C" fn fees_FeeRule_new_director(
    name: *const c_char,
    context: *mut c_void,
    release: ccm_release_fn,
    fee: fees_FeeRule_fee_fn,
    applies: fees_FeeRule_applies_fn,
    label: fees_FeeRule_label_fn,
    result_director: *mut *mut c_void,
    result: *mut *mut fees_FeeRule,
) -> ccm_status {
    ccm::guard(|| {
        // First: the context is released however the export ends, the name refused included.
        let managed = ManagedRef::new(context, release);
        let calls = FeeRuleCalls::new(fee, applies, label)?;
        let state = FeeRuleBase::new(ccm::str_in(name, "name")?);
        new_director(managed, calls, state, result_director, result);
        Ok(())
    })
}

#[unsafe(no_mangle)]
#[allow(clippy::too_many_arguments)]
pub extern "C" fn fees_FlatFee_new_director(
    fee: ccm_decimal,
    context: *mut c_void,
    release: ccm_release_fn,
    fee_fn: fees_FeeRule_fee_fn,
    applies: fees_FeeRule_applies_fn,
    label: fees_FeeRule_label_fn,
    result_director: *mut *mut c_void,
    result: *mut *mut fees_FeeRule,
) -> ccm_status {
    ccm::guard(|| {
        let managed = ManagedRef::new(context, release);
        let calls = FeeRuleCalls::new(fee_fn, applies, label)?;
        let state = FlatFee::new(ccm::dec(fee)?)?;
        new_director(managed, calls, state, result_director, result);
        Ok(())
    })
}

#[unsafe(no_mangle)]
#[allow(clippy::too_many_arguments)]
pub extern "C" fn fees_PercentFee_new_director(
    percent: ccm_decimal,
    minimum: ccm_decimal,
