        let calls = FeeRuleCalls::new(fee, applies, label)?;
        let state = PercentFee::new(ccm::dec(percent)?, ccm::dec(minimum)?);
        new_director(managed, calls, state, result_director, result);
        Ok(())
    })
}

/// A director's base calls (C#'s base.Fee(), base.Applies(), base.Label() and the façades'
/// bodies on a director): the ported class's own implementation, never the C# override.
#[unsafe(no_mangle)]
pub extern "C" fn fees_FeeRule_base_fee(
    self_: *const fees_FeeRule,
