}

#[unsafe(no_mangle)]
pub extern "C" fn fees_FlatFee_new(fee: ccm_decimal, result: *mut *mut fees_FeeRule) -> ccm_status {
    ccm::guard(|| {
        let rule: Arc<dyn FeeRule> = Arc::new(FlatFee::new(ccm::dec(fee)?)?);
        ccm::put(result, ccm::to_handle::<fees_FeeRule>(rule));
