#[unsafe(no_mangle)]
pub extern "C" fn fees_FlatFee_amount(self_: *const fees_FeeRule, result: *mut ccm_decimal) -> ccm_status {
    ccm::guard(|| {
        let rule: &dyn Any = &**ccm::from_handle(self_)?;
        let flat = rule
            .downcast_ref::<FlatFee>()
            .or_else(|| rule.downcast_ref::<FeeRuleDirector<FlatFee>>().map(|d| &d.state))
            .ok_or_else(|| Exception::invalid_operation("not a FlatFee"))?;
        ccm::put(result, ccm::dec_out(flat.amount()));
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn fees_PercentFee_new(
