//! The Rust of Fees.FeeRule, Fees.FlatFee, Fees.PercentFee, ported from C# (CodeCoreMorph, D-84).
//!
//! C# classes derive from `FeeRule`, `FlatFee` and `PercentFee` and override their virtual
//! members (D-87), so the hierarchy is a trait whose virtual members return `Result` (a C#
//! override may throw), and each class's own implementation of a virtual member takes the object
//! it runs on (`this`), so a base call made for a C# class's object still reaches its overrides.
use std::any::Any;

use codecoremorph_runtime::{Decimal, Exception, Result};

/// What every rule holds, whichever class it is: `FeeRule`'s own fields.
pub struct FeeRuleBase {
    name: String,
}

impl FeeRuleBase {
    /// C#'s `protected FeeRule(string name)`: a null name is the bridge's to refuse.
    pub fn new(name: impl Into<String>) -> FeeRuleBase {
        FeeRuleBase { name: name.into() }
    }

    /// `FeeRule`'s own `Applies`, for the object `this`.
    pub fn applies_impl(&self, _this: &(impl FeeRule + ?Sized), amount: Decimal) -> Result<bool> {
        Ok(amount > Decimal::ZERO)
    }

    /// `FeeRule`'s own `Label`, for the object `this`.
    pub fn label_impl(&self, _this: &(impl FeeRule + ?Sized)) -> Result<String> {
        Ok(self.name.clone())
    }
}

/// A rule that charges a fee on an amount (`Fees.FeeRule`, abstract).
pub trait FeeRule: Any + Send + Sync {
    /// `FeeRule`'s fields.
    fn base(&self) -> &FeeRuleBase;

    /// The rule's name in a schedule.
    fn name(&self) -> &str {
        &self.base().name
    }

    /// The fee before rounding (abstract).
    fn fee(&self, amount: Decimal) -> Result<Decimal>;

    /// Whether the rule charges anything on the amount (virtual).
    fn applies(&self, amount: Decimal) -> Result<bool> {
        self.base().applies_impl(self, amount)
    }

    /// The rule's label in a report (virtual; protected in C#).
    fn label(&self) -> Result<String> {
        self.base().label_impl(self)
    }

    /// The fee charged: rounded to cents, zero where the rule doesn't apply. Not virtual in
    /// C#: no implementation overrides it.
    fn charge(&self, amount: Decimal) -> Result<Decimal> {
        if self.applies(amount)? {
            round(self.fee(amount)?)
        } else {
            Ok(Decimal::ZERO)
        }
    }

    /// A line of a report: the rule's label and its charge. Not virtual in C#.
    fn describe(&self, amount: Decimal) -> Result<String> {
        Ok(format!("{}: {}", self.label()?, self.charge(amount)?))
    }
}

/// Rounds to cents, half away from zero (`FeeRule.Round`, protected static in C#).
pub fn round(value: Decimal) -> Result<Decimal> {
    value.round_away_from_zero(2)
}

/// The same fee on every amount.
pub struct FlatFee {
    base: FeeRuleBase,
    fee: Decimal,
}

impl FlatFee {
    pub fn new(fee: Decimal) -> Result<FlatFee> {
        if fee < Decimal::ZERO {
            return Err(Exception::argument_out_of_range("fee", "a fee can't be negative"));
        }
        Ok(FlatFee { base: FeeRuleBase::new("flat"), fee })
    }

    pub fn amount(&self) -> Decimal {
        self.fee
    }

    /// `FlatFee`'s own `Fee`, for the object `this` (this one, or a C# class's derived from it).
    pub fn fee_impl(&self, _this: &(impl FeeRule + ?Sized), _amount: Decimal) -> Result<Decimal> {
        Ok(self.fee)
    }
}

impl FeeRule for FlatFee {
    fn base(&self) -> &FeeRuleBase {
        &self.base
    }

    fn fee(&self, amount: Decimal) -> Result<Decimal> {
        self.fee_impl(self, amount)
    }
}

/// A percentage of the amount, from a minimum amount up.
pub struct PercentFee {
    base: FeeRuleBase,
    percent: Decimal,
    minimum: Decimal,
}

impl PercentFee {
    pub fn new(percent: Decimal, minimum: Decimal) -> PercentFee {
        PercentFee { base: FeeRuleBase::new("percent"), percent, minimum }
    }

    /// `PercentFee`'s own implementations, for the object `this`.
    pub fn fee_impl(&self, _this: &(impl FeeRule + ?Sized), amount: Decimal) -> Result<Decimal> {
        amount.checked_mul(self.percent)?.checked_div(Decimal::from(100))
    }

    pub fn applies_impl(&self, this: &(impl FeeRule + ?Sized), amount: Decimal) -> Result<bool> {
        Ok(self.base.applies_impl(this, amount)? && amount >= self.minimum)
    }

    pub fn label_impl(&self, this: &(impl FeeRule + ?Sized)) -> Result<String> {
        Ok(format!("{} {}%", this.name(), self.percent))
    }
}

impl FeeRule for PercentFee {
    fn base(&self) -> &FeeRuleBase {
        &self.base
    }

    fn fee(&self, amount: Decimal) -> Result<Decimal> {
        self.fee_impl(self, amount)
    }

    fn applies(&self, amount: Decimal) -> Result<bool> {
        self.applies_impl(self, amount)
    }

    fn label(&self) -> Result<String> {
        self.label_impl(self)
    }
}

