        Schedule::default()
    }

    fn rules(&self) -> MutexGuard<'_, Vec<Arc<dyn FeeRule>>> {
        self.rules.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    pub fn count(&self) -> i32 {
        i32::try_from(self.rules().len()).unwrap_or(i32::MAX)
    }

