    fn applies(&self, amount: Decimal) -> Result<bool> {
        Ok(self.base.applies_impl(self, amount)? && amount < d("10000"))
    }

    fn label(&self) -> Result<String> {
        Ok(format!("capped {}", self.base.label_impl(self)?))
    }
}

/// Rules.cs's DoubledFlat: twice the flat fee.
struct DoubledFlat {
    flat: FlatFee,
}

impl FeeRule for DoubledFlat {
    fn base(&self) -> &FeeRuleBase {
        self.flat.base()
    }

    fn fee(&self, amount: Decimal) -> Result<Decimal> {
        self.flat.fee_impl(self, amount)?.checked_mul(d("2"))
    }
}

/// Rules.cs's FailingFee: its fee throws an exception the library doesn't know.
struct FailingFee {
    base: FeeRuleBase,
}

impl FeeRule for FailingFee {
    fn base(&self) -> &FeeRuleBase {
        &self.base
    }

    fn fee(&self, _amount: Decimal) -> Result<Decimal> {
        Err(Exception::new("System.TimeZoneNotFoundException", "no fee today"))
    }
}

fn add_capped(schedule: &Schedule, name: &str) -> Weak<dyn FeeRule> {
    let rule: Arc<dyn FeeRule> = Arc::new(CappedFee::new(name, d("0.1"), d("100")));
    schedule.add(rule.clone());
    Arc::downgrade(&rule)
}

fn unheld() -> Weak<dyn FeeRule> {
    let rule: Arc<dyn FeeRule> = Arc::new(CappedFee::new("unheld", d("0.1"), d("100")));
    assert_eq!(rule.charge(d("10")).expect("a charge"), d("1.00"));
    Arc::downgrade(&rule)
}

#[test]
fn total_sums_every_rule() -> Result<()> {
    let schedule = Schedule::new();
    schedule.add(Arc::new(FlatFee::new(d("1"))?));
    schedule.add(Arc::new(PercentFee::new(d("10"), d("0"))));
    schedule.add(Arc::new(CappedFee::new("capped", d("0.5"), d("2"))));
    schedule.add(Arc::new(DoubledFlat { flat: FlatFee::new(d("0.5"))? }));
    assert_eq!(schedule.count(), 4);
    assert_eq!(schedule.total(d("10"))?, d("5.00"));
    Ok(())
}

#[test]
fn report_uses_each_rules_label() -> Result<()> {
    let schedule = Schedule::new();
    schedule.add(Arc::new(PercentFee::new(d("10"), d("0"))));
    schedule.add(Arc::new(CappedFee::new("c", d("0.5"), d("2"))));
    assert_eq!(schedule.report(d("10"))?, "percent 10%: 1\ncapped c: 2");
    Ok(())
}

#[test]
fn find_gives_back_the_same_object() -> Result<()> {
    let schedule = Schedule::new();
    let capped: Arc<dyn FeeRule> = Arc::new(CappedFee::new("mine", d("0.1"), d("5")));
    let flat: Arc<dyn FeeRule> = Arc::new(FlatFee::new(d("1"))?);
    schedule.add(capped.clone());
    schedule.add(flat.clone());
    let same = |found: Option<Arc<dyn FeeRule>>, rule: &Arc<dyn FeeRule>| {
        found.is_some_and(|f| std::ptr::addr_eq(Arc::as_ptr(&f), Arc::as_ptr(rule)))
    };
    assert!(same(schedule.find("mine"), &capped));
    assert!(same(schedule.find("flat"), &flat));
    assert!(schedule.find("none").is_none());
    Ok(())
}

#[test]
fn an_exception_from_an_override_reaches_the_caller() -> Result<()> {
    let schedule = Schedule::new();
    schedule.add(Arc::new(FlatFee::new(d("1"))?));
    schedule.add(Arc::new(FailingFee { base: FeeRuleBase::new("failing") }));
    let Err(e) = schedule.total(d("10")) else {
        panic!("the failing fee's exception was lost");
    };
    assert!(e.is("System.TimeZoneNotFoundException"));
    assert_eq!(e.message(), "no fee today");
    Ok(())
}

#[test]
fn a_rule_only_the_schedule_holds_stays_alive() -> Result<()> {
    let schedule = Schedule::new();
    add_capped(&schedule, "kept");
    assert_eq!(schedule.total(d("10"))?, d("1.00"));
    let Some(found) = schedule.find("kept") else {
        panic!("the schedule lost the rule it held");
    };
    let any: &dyn Any = &*found;
    let capped = any.downcast_ref::<CappedFee>().expect("a CappedFee");
    assert_eq!(capped.calls.load(Ordering::SeqCst), 1);
    Ok(())
}

#[test]
fn a_rule_nothing_holds_is_collected() {
    let rule = unheld();
    assert!(rule.upgrade().is_none());
}

#[test]
fn a_removed_rule_is_collected() {
    let schedule = Schedule::new();
    let rule = add_capped(&schedule, "gone");
    assert!(rule.upgrade().is_some());
    assert!(schedule.remove("gone"));
    assert!(!schedule.remove("gone"));
    assert!(rule.upgrade().is_none());
    assert_eq!(schedule.count(), 0);
}
